### acme/aidenhq agent/dropped-stopped-test (c132227608b7)
diff --git a/ops/compose-recreate.sh b/ops/compose-recreate.sh
index 0fac225..f63ea32 100755
--- a/ops/compose-recreate.sh
+++ b/ops/compose-recreate.sh
@@ -237,7 +237,8 @@ step() {

 # A service container (never a one-off) of this project, running or stopped, of a service this config no longer defines:
 # "<id> <service>". Stopped ones count: a module's data move stops the old container before this step, and a stopped
-# container is still one monitoring sees as a core service that is down.
+# container is still one monitoring sees as a core service that is down. A stopped service that is still configured is
+# not dropped -- the `grep -qxF "$service" <<< "$desired"` below skips it, so a stopped `board` is kept, not removed.
 dropped() {
   local desired="$1" id oneoff service
   for id in $(docker ps -aq --filter "label=com.docker.compose.project=$project" --filter label=com.docker.compose.oneoff=False); do
diff --git a/scripts/test/apply-compose.test.mjs b/scripts/test/apply-compose.test.mjs
index 420c915..4e20a11 100644
--- a/scripts/test/apply-compose.test.mjs
+++ b/scripts/test/apply-compose.test.mjs
@@ -74,7 +74,9 @@ case "$1" in
         exit "$code" ;;
     esac ;;
-  ps) cat "$dir/ids" ;;
+  ps)
+    # ps -q lists running containers only; -a adds the stopped ones, as the daemon does.
+    if [[ "$*" == *" -aq"* ]]; then cat "$dir/ids"; else cat "$dir/running-ids" 2>/dev/null || cat "$dir/ids"; fi ;;
   inspect)
@@ -107,6 +109,8 @@ function fixture({ containers = {}, services, hashes = {}, up = [["", 0]], rmFai
   writeFileSync(join(dir, "ids"), `${Object.keys(containers).join("\n")}\n`);
+  // `docker ps -q` (running only) versus `docker ps -aq` (every container): a stopped one is in the second list only.
+  writeFileSync(join(dir, "running-ids"), `${Object.entries(containers).filter(([, c]) => c.running === "true").map(([id]) => id).join("\n")}\n`);
@@ -173,8 +180,12 @@ test("containers of a service the config dropped are removed whether running or stopped; a CI one-off and a kept service never are", async () => {
   assert.equal(r.status, 0, r.out);
+  const scans = calls(r, "docker ps ");
+  for (const s of scans) assert.match(s, /^docker ps -aq /, "a scan lists the stopped containers too");
   assert.deepEqual(removals(r), ["docker rm -f gh1", "docker rm -f slack1"]);
+  assert.match(r.out, /compose: channel-slack-slack removed \(no longer in the config\)/);
 });
